} satisfies ChartConfig;
const dollars = (n: number) => money(Math.round(n) * 100).replace(/\.00$/, "");
export const CashFlow = defineUi<{
  list: readonly Transaction[];
  className?: string;
}>("CashFlow", ["list", "class"], (_props, {
